// schema.js - one registry of comparison metric identities. Human output and
// JSON output are rendered from the same entries, so a printed label can
// never drift from the JSON key that carries the same number.
//
// Plain JS ESM + JSDoc.

import { pyStr } from "./py.js";

/** One reported value with a single name for humans and machines. */
export class Metric {
  constructor(key, attribute, description, { summary = false, width = 0, kind = "text" } = {}) {
    Object.assign(this, { key, attribute, description, summary, width, kind });
    Object.freeze(this);
  }
  get deprecated_keys() { return this.attribute === this.key ? [] : [this.attribute]; }
  render(value) {
    if (this.kind === "integer" && Number.isInteger(value) && typeof value !== "boolean") return String(value).padStart(this.width, " ");
    return this.width ? pyStr(value).padStart(this.width, " ") : pyStr(value);
  }
}

