export const METRICS_BY_KEY = Object.freeze(Object.fromEntries([...METRICS, ...CAMPAIGN_METRICS].map((m) => [m.key, m])));
/** The view report is a separate namespace with its own lookup. */
export const VIEW_METRICS_BY_KEY = Object.freeze(Object.fromEntries(VIEW_METRICS.map((m) => [m.key, m])));
export const SUMMARY_METRICS = Object.freeze(METRICS.filter((m) => m.summary));
export const DEPRECATED_KEYS = Object.freeze(Object.fromEntries(METRICS.flatMap((m) => m.deprecated_keys.map((a) => [a, m.key]))));
/** Spellings `--census` accepts on a comparison, mapped to the report key. */
export const COMPARISON_CENSUS_KEYS = Object.freeze({ ...Object.fromEntries(METRICS.map((m) => [m.key, m.key])), ...DEPRECATED_KEYS });
export const VIEW_CENSUS_KEYS = Object.freeze(Object.fromEntries(VIEW_METRICS.map((m) => [m.key, m.key])));
export const SHIFT_METRICS_BY_KEY = Object.freeze(Object.fromEntries(SHIFT_METRICS.map((m) => [m.key, m])));
export const SHIFT_CENSUS_KEYS = Object.freeze(Object.fromEntries(SHIFT_METRICS.map((m) => [m.key, m.key])));

/** Render the one-line human summary from the registry. */
export function summaryLine(item) {
  const fields = SUMMARY_METRICS.map((m) => `${m.key}=${m.render(item[m.attribute])}`).join(" ");
  return `${fields} ${item.candidate}`;
}

/** Return the canonical JSON keys whose spelling changed. */
export function canonicalFields(item) {
  const out = {};
  for (const m of METRICS) if (m.deprecated_keys.length) out[m.key] = item[m.attribute];
  return out;
}

/** Return canonical and deprecated JSON keys for selected metrics. */
export function selectedFields(item, keys) {
  const payload = {};
  for (const key of keys) {
    const m = METRICS_BY_KEY[key];
    const value = item[m.attribute];
    payload[m.key] = value;
    for (const alias of m.deprecated_keys) payload[alias] = value;
  }
  return payload;
}

export const EXPLAIN_WIDTH = 88;

/** Greedy word wrap (textwrap.wrap without hyphen splitting). */
function wrap(text, width, indent) {
  const words = text.split(/\s+/).filter(Boolean);
  const lines = [];
  let cur = indent;
  for (const w of words) {
    if (cur.length > indent.length && cur.length + 1 + w.length > width) { lines.push(cur); cur = indent + w; }
    else cur = cur.length > indent.length ? `${cur} ${w}` : cur + w;
  }
  if (cur.length > indent.length) lines.push(cur);
  return lines;
}

/** Return the printed registry: label, JSON key, and meaning. */
export function explainKeysText() {
  const header = "Comparison keys. The printed label and the JSON key are the same string.\n"
    + "Deprecated JSON keys are still emitted beside the canonical key for one release;\n"
    + "new consumers should read the canonical key. Every key is followed by its meaning.\n";
  const titles = ["key", "line", "deprecated json key", ""];
  const describe = (ms) => ms.map((m) => [m.key, m.summary ? "yes" : "-", m.deprecated_keys.join(", ") || "-", m.description]);
  const rows = describe(METRICS), campaign = describe(CAMPAIGN_METRICS), view = describe(VIEW_METRICS), shift = describe(SHIFT_METRICS), command = describe(COMMAND_METRICS);
  const all = [...rows, ...campaign, ...view, ...shift, ...command];
  const widths = [0, 1, 2].map((c) => Math.max(titles[c].length, ...all.map((r) => r[c].length)));
  const fmt = (row) => [0, 1, 2].map((c) => row[c].padEnd(widths[c])).join("  ").replace(/\s+$/, "");
  const fmtRows = (items) => items.flatMap((row) => [fmt(row), ...wrap(row[3], EXPLAIN_WIDTH, "    ")]);
  const sep = widths.map((w) => "-".repeat(w)).join("  ");
  return [header, fmt(titles), sep, ...fmtRows(rows), "",
    "Campaign report keys (campaign --json / --json-summary).", "", fmt(titles), sep, ...fmtRows(campaign), "",
    "Aligned mechanism view keys (view / view-dumps). These count aligned rows, not",
    "positional words, so a spelling shared with the comparison registry above is a",
    "different number. Nested keys (hunks, lanes, webs) are listed with the rest.", "", fmt(titles), sep, ...fmtRows(view), "",
    "Shiftability keys (shift audit and shift rehearse). A third namespace: these count",
    "words in a linked image, pins in a linker script, and what a relink changed or left",
    "unmoved, so a spelling shared with either registry above is a different thing. Nested",
    "keys (regions, pins, hits, rules, checksums, runs) are listed with the rest.", "", fmt(titles), sep, ...fmtRows(shift), "",
    "Command result keys. These describe what one invocation decided rather than what",
    "the two inputs look like: acceptance, and the --census predicate results (exit 3",
    "when any predicate fails, distinct from the exit 1 of --fail-on-mismatch).", "", fmt(titles), sep, ...fmtRows(command)].join("\n");
}
